CREATE TABLE page_views (ts DateTime, url String, ms UInt32)
ENGINE = MergeTree ORDER BY (url, ts);

-- Many rows per INSERT, sent in a text format
INSERT INTO page_views FORMAT JSONEachRow
{"ts": "2025-03-01 10:00:00", "url": "/home", "ms": 120}
{"ts": "2025-03-01 10:00:05", "url": "/cart", "ms": 340}

-- INSERT ... SELECT from a table function (here: generated data)
INSERT INTO page_views
SELECT now() - number, concat('/p/', toString(number % 50)), rand() % 1000
FROM numbers(100000);

-- Many small inserts from many clients? Let the server batch them:
INSERT INTO page_views SETTINGS async_insert = 1, wait_for_async_insert = 1
VALUES (now(), '/home', 99);

SELECT count() FROM page_views;   -- 100003

CREATE TABLE logs (tenant UInt16, level LowCardinality(String), ts DateTime, msg String)
ENGINE = MergeTree ORDER BY (tenant, level, ts);

INSERT INTO logs SELECT number % 100, ['info','warn','error'][number % 3 + 1],
       now() - number, 'm' FROM numbers(2000000);

-- Filter on the key prefix: only a few granules are read
EXPLAIN indexes = 1 SELECT count() FROM logs WHERE tenant = 7 AND level = 'error';
--   PrimaryKey  Keys: tenant, level ... Granules: 3/245

-- Filter on ts alone (third key column): no pruning
EXPLAIN indexes = 1 SELECT count() FROM logs WHERE ts > now() - 60;
--   PrimaryKey  Keys: ts ... Granules: 245/245

CREATE TABLE users (id UInt64, email String, plan LowCardinality(String))
ENGINE = MergeTree ORDER BY id;
INSERT INTO users VALUES (1, 'a@x.io', 'free'), (2, 'b@x.io', 'pro'), (3, 'c@x.io', 'free');

-- Lightweight delete: rows disappear from results immediately
DELETE FROM users WHERE id = 3;

-- Mutation: rewrites affected parts in the background
ALTER TABLE users UPDATE plan = 'pro' WHERE id = 1 SETTINGS mutations_sync = 1;

SELECT * FROM users ORDER BY id;
-- 1  a@x.io  pro
-- 2  b@x.io  pro

SELECT command, is_done FROM system.mutations WHERE table = 'users';
-- (UPDATE _row_exists = 0 WHERE id = 3)   1   <- the DELETE only wrote a mask
-- (UPDATE plan = 'pro' WHERE id = 1)      1

CREATE TABLE user_profile (id UInt64, plan String, ver UInt64)
ENGINE = ReplacingMergeTree(ver) ORDER BY id;

INSERT INTO user_profile VALUES (1, 'free', 1);
INSERT INTO user_profile VALUES (1, 'pro', 2);       -- an "update" is a new version

SELECT count() FROM user_profile;                    -- 2 (not merged yet)
SELECT * FROM user_profile FINAL;                    -- 1  pro  2
SELECT id, argMax(plan, ver) FROM user_profile GROUP BY id;   -- 1  pro

CREATE TABLE daily_users
(day Date, users AggregateFunction(uniq, UInt64))
ENGINE = AggregatingMergeTree ORDER BY day;

INSERT INTO daily_users SELECT today(), uniqState(toUInt64(number % 10)) FROM numbers(100);
INSERT INTO daily_users SELECT today(), uniqState(toUInt64(number % 20)) FROM numbers(100);
SELECT day, uniqMerge(users) FROM daily_users GROUP BY day;   -- today  20

CREATE TABLE clicks (ts DateTime, page String, user UInt64)
ENGINE = MergeTree ORDER BY (page, ts);

CREATE TABLE clicks_per_min
(minute DateTime, page String,
 hits SimpleAggregateFunction(sum, UInt64), users AggregateFunction(uniq, UInt64))
ENGINE = AggregatingMergeTree ORDER BY (page, minute);

CREATE MATERIALIZED VIEW clicks_mv TO clicks_per_min AS
SELECT toStartOfMinute(ts) AS minute, page,
       count() AS hits, uniqState(user) AS users
FROM clicks GROUP BY minute, page;

INSERT INTO clicks VALUES ('2025-05-01 12:00:10', '/a', 1), ('2025-05-01 12:00:20', '/a', 2);
INSERT INTO clicks VALUES ('2025-05-01 12:00:30', '/a', 1);

-- Read with aggregation: the target holds partial rows until merged
SELECT minute, page, sum(hits) AS hits, uniqMerge(users) AS users
FROM clicks_per_min GROUP BY minute, page;
-- 2025-05-01 12:00:00  /a  3  2

CREATE TABLE countries (code String, name String) ENGINE = MergeTree ORDER BY code;
INSERT INTO countries VALUES ('DE', 'Germany'), ('FR', 'France');

CREATE TABLE sales (country String, amount UInt32) ENGINE = MergeTree ORDER BY country;
INSERT INTO sales VALUES ('DE', 10), ('DE', 5), ('FR', 7);

-- Big table left, small table right
SELECT c.name, sum(s.amount) AS total
FROM sales AS s INNER JOIN countries AS c ON s.country = c.code
GROUP BY c.name ORDER BY total DESC;            -- Germany 15 / France 7

-- Same enrichment with a dictionary lookup
CREATE DICTIONARY country_dict (code String, name String)
PRIMARY KEY code
SOURCE(CLICKHOUSE(TABLE 'countries'))
LAYOUT(COMPLEX_KEY_HASHED()) LIFETIME(MIN 300 MAX 600);

SELECT dictGet('country_dict', 'name', tuple(country)) AS name, sum(amount)
FROM sales GROUP BY name ORDER BY name;         -- France 7 / Germany 15

CREATE TABLE requests
(tenant UInt16, ts DateTime, trace_id String, user_id UInt64, ms UInt32,
 INDEX trace_bf trace_id TYPE bloom_filter(0.01) GRANULARITY 4)
ENGINE = MergeTree ORDER BY (tenant, ts);

INSERT INTO requests SELECT number % 10, now() - number, toString(cityHash64(number)),
       number % 5000, rand() % 900 FROM numbers(1000000);

-- Bloom filter skips blocks for a needle-in-haystack lookup
EXPLAIN indexes = 1 SELECT * FROM requests WHERE trace_id = toString(cityHash64(42));

-- Projection: a second sort order for per-user queries
ALTER TABLE requests ADD PROJECTION by_user (SELECT * ORDER BY user_id);
ALTER TABLE requests MATERIALIZE PROJECTION by_user SETTINGS mutations_sync = 1;

SELECT count(), avg(ms) FROM requests WHERE user_id = 42;   -- 200  (uses by_user)
